// ═══════════════════════════════════════════════════════════════════════
// ║ 79s-lab-backdrops.js — round 106 (Kris: "some of the backdrops of the adventure sites look very weird, especially when you are in the
// ║ clouds and such. We need to make these background better, suggest some ways of doing this").
// ║ What is wrong today (eight floors caught in the Site Lab), and seven ways to fix it — ✓ do · ✎ change · ✕ skip each.
// ║ Picks: 'backdrop-<id>'.
// ═══════════════════════════════════════════════════════════════════════
(function(){ if(typeof LAB_TABS==='undefined')return;
  var SHOTS=[["s3_tower", "Starlit Observatory \u00b7 floor 5 \u2014 a sea of clouds", "data:image/jpeg;base64,"], ["s3_b_sky_cloister", "Sky Cloister \u00b7 floor 4 \u2014 clouds", "data:image/jpeg;base64,"], ["s2_tower", "Frost Cathedral \u00b7 floor 5 \u2014 the deep sea", "data:image/jpeg;base64,"], ["s4_tower", "Dawn Sanctum \u00b7 floor 6 \u2014 lava", "data:image/jpeg;base64,"], ["mage_conductor", "The Conductor's Spire \u00b7 floor 2 \u2014 stars", "data:image/jpeg;base64,"], ["s2_b_moonglass", "Moonglass Spire \u00b7 floor 4 \u2014 the deep sea", "data:image/jpeg;base64,"], ["s1_tower", "Silverwood Palace \u00b7 floor 4 \u2014 treetops", "data:image/jpeg;base64,"], ["s4_b_spiral_chasm", "Spiral Chasm \u00b7 floor 3 \u2014 the abyss", "data:image/jpeg;base64,"]];
  var esc=function(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;'); };
  var P=function(k){ return LabApp.picks[k]||{}; }, V=function(k){ return P(k).verdict||null; };
  var WRONG=[['Hard square edges','Where a floor ends the backdrop shows through in tile-sized steps, so the floor looks cut out with scissors, not built.'],
    ['No thickness','A floor high in a tower floats like a flat sheet: no rim, no wall underneath, no shadow on what lies below.'],
    ['Too big and too close','The clouds and waves are painted at the same size as the floor, so they read as a pattern on the ground, not something far below.'],
    ['Floor and void look alike','On the starry and cloudy floors, holes and edges are hard to tell from floor: you are not sure where you can walk.'],
    ['Blank wall tops','The tops of walls are flat white or grey blocks with nothing painted on them.']];
  var FIX=[['rim','A built edge on every floor','Along every edge that meets the backdrop: a stone lip on top, then a short cliff or wall face hanging below (from the site\'s own stone), and a soft shadow on the backdrop. The steps of the tile grid are rounded off. One painted sheet per element (6 sheets).'],
    ['far','Push the backdrop far away','Paint the clouds, waves, lava and treetops at a third of today\'s size, darker and a little blurred, with a gradient from the floor\'s edge outward — so they sit far below, not on the floor.'],
    ['layers','Two moving layers, not one','A slow far layer (sea, cloud sea, stars) and a faster near layer drifting past (wisps of cloud, spray, embers, leaves), so you feel the height. Already part of the code for some kinds; this does it for every kind.'],
    ['tower','You are inside a tower','Upper tower floors stop floating in open sky: a ring of the tower\'s own outer wall and windows fills the empty space, with the sky and the land far below seen through the windows. Castles and mage towers alike.'],
    ['island','Floating islands, on purpose','Keep the open sky, but make each floor clearly an island of rock: the underside drawn as hanging rock and roots (like the world\'s floating rocks), a few small islands drifting in the distance.'],
    ['caps','Paint the wall tops','The tops of walls get the painted bricks of round 103 (stone caps, a little moss), so no wall is a blank white block.'],
    ['clear','Clear floor, plain void','Where the void and the floor share a look (stars, clouds), the floor always gets solid stone and the void stays darker with a vignette — never the same pattern on both.']];
  LAB_TABS.push({ id:'backdrop', name:'Site backdrops',
    blurb:'<b>Round 106 — what fills the space round a floor.</b> Eight floors as they look today, what is wrong, and seven ways to fix it.',
    designs:FIX.map(function(x){ return {id:x[0],name:'Backdrop: '+x[1]}; }),
    render:function(){ return LBR.sec('Today','eight floors from the Site Lab — clouds, the deep sea, lava, stars, treetops, the abyss')+
        '<div class="bd-shots">'+SHOTS.map(function(s){ return '<figure><img src="'+s[2]+'" alt="'+esc(s[1])+'" loading="lazy"><figcaption>'+esc(s[1])+'</figcaption></figure>'; }).join('')+'</div>'+
        LBR.sec('What is wrong','seen in the pictures above')+'<ul class="bd-wrong">'+WRONG.map(function(w){ return '<li><b>'+esc(w[0])+'.</b> '+esc(w[1])+'</li>'; }).join('')+'</ul>'+
        LBR.sec('Ways to fix it','✓ do · ✎ change · ✕ skip — they combine (for example a built edge + far backdrop + layers); "inside a tower" and "floating islands" are the two different looks for upper floors')+
        '<table class="tl bd-t"><tbody>'+FIX.map(function(x){ var k='backdrop-'+x[0], v=V(k);
          return '<tr class="tl-'+(v||'x')+'"><td style="width:22%"><b>'+esc(x[1])+'</b></td><td>'+esc(x[2])+'</td><td><span class="pz-seg bd-seg" data-k="'+k+'">'+[['pick','✓ Do'],['change','✎ Change'],['cut','✕ Skip']].map(function(o){ return '<button class="vbtn bd-sg'+(v===o[0]?' on '+o[0]:'')+'" data-v="'+o[0]+'">'+o[1]+'</button>'; }).join('')+'</span></td><td><input class="tl-n bd-n" data-k="'+k+'" value="'+esc(P(k).notes||'')+'" placeholder="Note…"></td></tr>'; }).join('')+'</tbody></table>'; } });
  document.addEventListener('click',function(e){ var sg=e.target.closest&&e.target.closest('.bd-sg'); if(!sg)return; var seg=sg.parentNode, k=seg.dataset.k, nv=V(k)===sg.dataset.v?null:sg.dataset.v, p=LabApp.picks[k]=LabApp.picks[k]||{}; p.verdict=nv; LabApp.persist(k);
    [].forEach.call(seg.children,function(x){ x.className='vbtn bd-sg'+(x.dataset.v===nv?' on '+nv:''); }); seg.closest('tr').className='tl-'+(nv||'x'); });
  document.addEventListener('change',function(e){ var t=e.target.closest&&e.target.closest('.bd-n'); if(!t)return; var p=LabApp.picks[t.dataset.k]=LabApp.picks[t.dataset.k]||{}; p.notes=t.value; LabApp.persist(t.dataset.k); });
  var st=document.createElement('style'); st.textContent='.bd-shots{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:10px;margin:8px 0 14px}.bd-shots figure{margin:0;background:#0b121c;border:1px solid #243246;border-radius:8px;overflow:hidden}.bd-shots img{display:block;width:100%;height:auto}.bd-shots figcaption{font:12px "Segoe UI",sans-serif;color:#b8c8dc;padding:5px 8px}'+
    '.bd-wrong{margin:4px 0 14px 18px;font-size:13px;color:#d8e0ec}.bd-wrong li{margin:3px 0}.bd-t td{font-size:12.5px}.bd-sg{padding:4px 8px;font-size:12px;opacity:.75}.bd-sg.on{opacity:1}.bd-sg.on.pick{background:#1f6a3a;border-color:#8fe8a0;color:#fff}.bd-sg.on.change{background:#6a5a1a;border-color:#ffd870;color:#fff}.bd-sg.on.cut{background:#6a2a2a;border-color:#ff9a8a;color:#fff}';
  document.head.appendChild(st);
  if(typeof LAB_ACTIVE!=='undefined')LAB_ACTIVE.unshift('backdrop');
  if(typeof LTODO!=='undefined')LTODO.add({id:'backdrop',label:'🌫 Site backdrops: ✓ / ✎ / ✕ the seven fixes',where:'Site backdrops tab',done:function(){ return FIX.every(function(x){ return !!V('backdrop-'+x[0]); }); },go:function(){ LTODO.goTo('backdrop','.bd-t',0); }});
})();
